func oddPositions(s: String): String {
    var out = ""
    let data = s.toArray()
    for (i in 0..data.size) { if (i % 2 == 0) { out += data[i].toString() } }
    out
}

main() {
println(oddPositions("中文A") == "中A")
println(oddPositions("abcd") == "ac")
}

func stripTag(s: String, tag: String): String {
    s.replace(tag, "")
}

main() {
println(stripTag("file.bak.bak", ".bak") == "file.bak")
println(stripTag("a-x-b", "-x") == "a-x-b")
}

func lastField(s: String, limit: Int64): String {
    let parts = s.split("|")
    if (parts.size == 0 || limit == 0) { return "" }
    parts[parts.size - 1]
}

main() {
println(lastField("a|b|c", 2) == "b|c")
println(lastField("a||", 2) == "|")
}

func stripEndSet(s: String, marks: String): String {
    s.removeSuffix(marks)
}

main() {
println(stripEndSet("abc!!!?", "!?") == "abc")
println(stripEndSet("水甲乙甲", "甲乙") == "水")
}
